def compute(vars):
    issued_securities = vars["v1"]
    exercise_price = vars["v2"]
    total_value_millions = issued_securities * exercise_price / 1000000

    return {
        "value": total_value_millions,
        "trace": {
            "issued_securities": issued_securities,
            "exercise_price": exercise_price,
            "total_value": issued_securities * exercise_price,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
